import { getSession } from './session';

export async function upload(file: Blob) {
  const session = await getSession();
  // token issued once, reused for the whole upload
  for (const chunk of chunks(file, 8 * 1024 * 1024)) {
    await fetch('/api/chunk', { method: 'POST', headers: { authorization: session.token }, body: chunk });
  }
}

function* chunks(file: Blob, size: number) {
  for (let at = 0; at < file.size; at += size) yield file.slice(at, at + size);
}

